\documentclass{article}
\usepackage[utf8]{inputenc} % Permite tildes y caracteres en español
\usepackage{listings}       % Paquete principal para formatear código
\usepackage{xcolor}         % Paquete para darle color a la sintaxis

% Configuración del estilo de código personalizado
\lstset{
    backgroundcolor=\color{gray!10},   % Fondo gris claro
    basicstyle=\ttfamily\small,        % Tipografía monoespaciada para el código
    breaklines=true,                   % Ajuste automático de líneas largas
    keywordstyle=\color{blue},         % Palabras clave en azul
    commentstyle=\color{green!60!black}, % Comentarios en verde oscuro
    stringstyle=\color{orange},        % Cadenas de texto en naranja
    numbers=left,                      % Números de línea a la izquierda
    numberstyle=\tiny\color{gray},     % Formato de los números de línea
    frame=single,                      % Cuadro alrededor del bloque de código
    captionpos=b                       % Posición del título (abajo)
}

\begin{document}

\title{Ejemplo de Código en \LaTeX}
\author{Tu Nombre}
\date{\today}
\maketitle

A continuación se muestra un bloque de código de ejemplo en Python:

% Bloque de declaración de código
\begin{lstlisting}[language=Python, caption={Script básico en Python}]
def saludar(nombre):
    # Esto es un comentario en Python
    mensaje = f"Hola, {nombre}, bienvenido a LaTeX."
    print(mensaje)

# Llamada a la función
saludar("Mundo")
\end{lstlisting}

\end{document}

